SELECT 
FROM TBL_TREASURY_PARTNER_TYPE


        AND TYPE_CODE LIKE CONCAT('%', #{params.typeCode}, '%')


        AND TYPE_NAME LIKE CONCAT('%', #{params.typeName}, '%')


        AND IS_ENABLED = #{params.isEnabled}


        AND CATEGORY = #{params.category}


        AND ORG_ID = #{params.orgId}


ORDER BY SORT_ORDER ASC, CREATE_TIME DESC

